import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";
import { flyGeospatialCameraToAsync } from "@babylonjs/lite";

export interface Place { yaw: number; pitch: number; radius: number; center: { x: number; y: number; z: number } }

const TWO_PI = Math.PI * 2;
const EPS = 1e-4;

function angularDiff(a: number, b: number): number {
  let d = (a - b) % TWO_PI;
  if (d > Math.PI) d -= TWO_PI;
  if (d < -Math.PI) d += TWO_PI;
  return Math.abs(d);
}

function isAtPlace(camera: GeospatialCamera, place: Place): boolean {
  return angularDiff(camera.yaw, place.yaw) <= EPS &&
    Math.abs(camera.pitch - place.pitch) <= EPS &&
    Math.abs(camera.radius - place.radius) <= EPS &&
    Math.abs(camera.center.x - place.center.x) <= EPS && ...;
}

export function flyToPlace(camera: GeospatialCamera, scene: SceneContext, place: Place, durationMs: number): Promise<boolean> {
  let stopped = false;
  let settled = false;
  // Cancel any existing fly? flyGeospatialCameraToAsync likely does. But we can call previous if present.
  const existing = camera._cancelFly;
