    pitch: place.pitch,
    radius: place.radius,
    center: { x: place.center.x, y: place.center.y, z: place.center.z },
    durationMs,
  });
  // Wrap current cancel to mark stopped.
  const current = camera._cancelFly;
  if (current) {
    camera._cancelFly = () => {
      if (!stopped) stopped = true;
